package com.quincaisoft.inventory.application;
import com.quincaisoft.inventory.api.*;import com.quincaisoft.inventory.infrastructure.*;import com.quincaisoft.finance.api.FinanceService;import com.quincaisoft.shared.*;
import jakarta.persistence.*;import org.springframework.stereotype.Service;import java.util.*;import java.time.*;import java.util.function.*;
import static com.quincaisoft.inventory.application.InventoryCommands.*;
@Service public class DefaultInventoryQuality implements InventoryQuality {
 private final EntityManager em;private final ScopedTransactions tx;private final StockService stock;private final FinanceService finance;private final InventoryCommands commands;
 public DefaultInventoryQuality(EntityManager em,ScopedTransactions tx,StockService stock,FinanceService finance){this.em=em;this.tx=tx;this.stock=stock;this.finance=finance;commands=new InventoryCommands(em);}
 private StockBalance balance(UUID warehouse,UUID product){stock.requireWarehouse(warehouse);var s=TenantContext.current();em.createNativeQuery("select id from warehouse where tenant_id=:t and company_id=:c and branch_id=:b and id=:w for update").setParameter("t",s.tenantId()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("w",warehouse).getSingleResult();var b=em.find(StockBalance.class,new StockBalance.Key(s.tenantId(),s.companyId(),warehouse,product),LockModeType.PESSIMISTIC_WRITE);if(b==null||!b.branchId.equals(s.branchId()))throw new NoSuchElementException("Stock position not found");return b;}
 private InventoryLot lot(UUID id){var s=TenantContext.current();var l=em.find(InventoryLot.class,new InventoryLot.Key(s.tenantId(),s.companyId(),id));if(l==null||!l.branchId.equals(s.branchId()))throw new NoSuchElementException("Lot not found");return l;}
 private InventoryRecall recall(UUID id){var s=TenantContext.current();var r=em.find(InventoryRecall.class,new InventoryRecall.Key(s.tenantId(),s.companyId(),id),LockModeType.PESSIMISTIC_WRITE);if(r==null||!r.branchId.equals(s.branchId()))throw new NoSuchElementException("Recall not found");return r;}
 private Lot view(InventoryLot l){return new Lot(l.id,l.warehouseId,l.productId,l.lotNumber,""+l.quantityMilli,""+l.quarantinedMilli,l.expiresOn,l.sourceReference,""+l.version);}
 private Recall view(InventoryRecall r){return new Recall(r.id,r.lotId,""+r.quantityMilli,r.status,r.businessDate,r.evidenceReference,""+r.version);}
 private Reservation view(InventoryReservation r){return new Reservation(r.id,r.warehouseId,r.productId,""+r.quantityMilli,""+r.releasedMilli,r.status,r.sourceReference,""+r.version);}
 public List<Lot> lots(){return tx.execute(()->em.createQuery("select l from InventoryLot l order by l.createdAt desc,l.id",InventoryLot.class).setMaxResults(200).getResultList().stream().map(this::view).toList());}
 public List<Recall> recalls(){return tx.execute(()->em.createQuery("select r from InventoryRecall r order by r.createdAt desc,r.id",InventoryRecall.class).setMaxResults(200).getResultList().stream().map(this::view).toList());}
 public List<Reservation> reservations(){return tx.execute(()->em.createQuery("select r from InventoryReservation r order by r.createdAt desc,r.id",InventoryReservation.class).setMaxResults(200).getResultList().stream().map(this::view).toList());}
 public Lot registerLot(RegisterLot c){long q=quantity(c.quantityMilli(),false);text(c.lotNumber(),120);text(c.sourceReference(),240);text(c.reason(),2000);return tx.execute(()->commands.once(c.operationId(),"LOT_REGISTER|"+c,"INVENTORY_LOT",Lot.class,()->{
  var b=balance(c.warehouseId(),c.productId());long tracked=em.createQuery("select coalesce(sum(l.quantityMilli),0) from InventoryLot l where l.warehouseId=:w and l.productId=:p",Long.class).setParameter("w",c.warehouseId()).setParameter("p",c.productId()).getSingleResult();if(Math.addExact(tracked,q)>b.quantityMilli)throw new IllegalArgumentException("Lot registration exceeds reconciled physical stock");
  var s=TenantContext.current();var l=new InventoryLot();l.tenantId=s.tenantId();l.companyId=s.companyId();l.branchId=s.branchId();l.id=UUID.randomUUID();l.warehouseId=c.warehouseId();l.productId=c.productId();l.lotNumber=c.lotNumber().trim();l.quantityMilli=q;l.expiresOn=c.expiresOn();l.sourceReference=c.sourceReference();l.createdBy=s.actorId();l.createdAt=Instant.now();em.persist(l);em.flush();return view(l);
 },Lot::id));}
 public Recall draftRecall(DraftRecall c){long q=quantity(c.quantityMilli(),false);text(c.reason(),2000);if(c.businessDate()==null)throw new IllegalArgumentException("Business date required");return tx.execute(()->commands.once(c.operationId(),"RECALL_DRAFT|"+c,"INVENTORY_RECALL",Recall.class,()->{var l=lot(c.lotId());if(q>l.quantityMilli-l.quarantinedMilli)throw new IllegalArgumentException("Recall exceeds available lot quantity");var s=TenantContext.current();var r=new InventoryRecall();r.tenantId=s.tenantId();r.companyId=s.companyId();r.branchId=s.branchId();r.id=UUID.randomUUID();r.lotId=l.id;r.quantityMilli=q;r.status="DRAFT";r.businessDate=c.businessDate();r.reason=c.reason();r.createdBy=s.actorId();r.createdAt=Instant.now();em.persist(r);em.flush();return view(r);},Recall::id));}
 public Recall approve(UUID id,Action c){return action(id,c,"APPROVE",r->{if(!r.status.equals("DRAFT"))throw new IllegalStateException("Draft recall required");if(r.createdBy.equals(TenantContext.current().actorId()))throw new IllegalStateException("Independent approver required");r.approvedBy=TenantContext.current().actorId();r.status="APPROVED";});}
 public Recall block(UUID id,Action c){return action(id,c,"BLOCK",r->{if(!r.status.equals("APPROVED"))throw new IllegalStateException("Approved recall required");finance.requireOpenPeriod(r.businessDate);var l=lot(r.lotId);var b=balance(l.warehouseId,l.productId);em.lock(l,LockModeType.PESSIMISTIC_WRITE);em.refresh(l);if(r.quantityMilli>l.quantityMilli-l.quarantinedMilli||r.quantityMilli>b.available())throw new IllegalStateException("Lot quantity is already blocked, reserved or unavailable");l.quarantinedMilli=Math.addExact(l.quarantinedMilli,r.quantityMilli);b.quarantinedMilli=Math.addExact(b.quarantinedMilli,r.quantityMilli);r.status="QUARANTINED";});}
 public Recall recover(UUID id,Action c){return disposition(id,c,false);}
 public Recall dispose(UUID id,Action c){return disposition(id,c,true);}
 private Recall disposition(UUID id,Action c,boolean disposal){text(c.evidenceReference(),240);return action(id,c,disposal?"DISPOSE":"RECOVER",r->{if(!r.status.equals("QUARANTINED"))throw new IllegalStateException("Quarantined recall required");finance.requireOpenPeriod(r.businessDate);var l=lot(r.lotId);var b=balance(l.warehouseId,l.productId);em.lock(l,LockModeType.PESSIMISTIC_WRITE);em.refresh(l);if(l.quarantinedMilli<r.quantityMilli||b.quarantinedMilli<r.quantityMilli)throw new IllegalStateException("Quarantine reconciliation required");l.quarantinedMilli=Math.subtractExact(l.quarantinedMilli,r.quantityMilli);b.quarantinedMilli=Math.subtractExact(b.quarantinedMilli,r.quantityMilli);
  if(disposal){l.quantityMilli=Math.subtractExact(l.quantityMilli,r.quantityMilli);em.flush();var issue=stock.issue(l.warehouseId,l.productId,r.quantityMilli,derived(c.operationId(),"disposal"),c.reason());if(issue.valueXaf()>0)finance.post(r.id,derived(c.operationId(),"journal"),r.businessDate,"RECALL_DISPOSAL",List.of(new FinanceService.Entry("INVENTORY_LOSS",issue.valueXaf(),0),new FinanceService.Entry("MERCHANT_INVENTORY",0,issue.valueXaf())));}
  r.evidenceReference=c.evidenceReference();r.status=disposal?"DISPOSED":"RECOVERED";
 });}
 private Recall action(UUID id,Action c,String verb,Consumer<InventoryRecall> work){long version=quantity(c.version(),true);text(c.reason(),2000);return tx.execute(()->commands.once(c.operationId(),"RECALL_"+verb+"|"+id+"|"+c,"INVENTORY_RECALL",Recall.class,()->{var r=recall(id);if(r.version!=version)throw new RevisionConflict("Recall changed");work.accept(r);em.flush();return view(r);},Recall::id));}
 public Reservation reserve(Reserve c){long q=quantity(c.quantityMilli(),false);text(c.sourceReference(),240);text(c.reason(),2000);return tx.execute(()->commands.once(c.operationId(),"RESERVE|"+c,"INVENTORY_RESERVATION",Reservation.class,()->{var b=balance(c.warehouseId(),c.productId());if(q>b.available())throw new IllegalArgumentException("Insufficient available stock for exclusive central reservation");b.reservedMilli=Math.addExact(b.reservedMilli,q);var s=TenantContext.current();var r=new InventoryReservation();r.tenantId=s.tenantId();r.companyId=s.companyId();r.branchId=s.branchId();r.id=UUID.randomUUID();r.warehouseId=c.warehouseId();r.productId=c.productId();r.quantityMilli=q;r.status="ACTIVE";r.sourceReference=c.sourceReference();r.reason=c.reason();r.createdBy=s.actorId();r.createdAt=Instant.now();em.persist(r);em.flush();return view(r);},Reservation::id));}
 public Reservation release(UUID id,Release c){long q=quantity(c.quantityMilli(),false),version=quantity(c.version(),true);text(c.reason(),2000);return tx.execute(()->commands.once(c.operationId(),"RELEASE|"+id+"|"+c,"INVENTORY_RESERVATION",Reservation.class,()->{var s=TenantContext.current();var r=em.find(InventoryReservation.class,new InventoryReservation.Key(s.tenantId(),s.companyId(),id));if(r==null||!r.branchId.equals(s.branchId()))throw new NoSuchElementException("Reservation not found");var b=balance(r.warehouseId,r.productId);em.lock(r,LockModeType.PESSIMISTIC_WRITE);em.refresh(r);if(r.version!=version)throw new RevisionConflict("Reservation changed");if(!r.status.equals("ACTIVE")||q>r.quantityMilli-r.releasedMilli)throw new IllegalArgumentException("Release exceeds remaining reservation");b.reservedMilli=Math.subtractExact(b.reservedMilli,q);r.releasedMilli=Math.addExact(r.releasedMilli,q);if(r.releasedMilli==r.quantityMilli)r.status="RELEASED";em.flush();return view(r);},Reservation::id));}
}
